"""Data model and expression evaluation for a small file-based build engine."""
import os
import re
import sys

VERSION = '1.14.0.git'

class NinjaError(Exception):
    def __init__(self, message, kind='error', code=1):
        self.message, self.kind, self.code = message, kind, code
        super().__init__(message)


def out(text):
    sys.stdout.write(text)
    sys.stdout.flush()


def err(text):
    sys.stderr.write(text)
    sys.stderr.flush()


def warning(text):
    err('ninja: warning: ' + text + '\n')


def canonical(path):
    if not path:
        raise NinjaError('empty path')
    # Manifest paths are lexical, not real paths; do not resolve symlinks.
    p = os.path.normpath(path)
    if p.startswith('//'):
        p = '/' + p.lstrip('/')
    return p


def quote(path):
    if path and re.fullmatch(r'[a-zA-Z0-9_+./-]+', path):
        return path
    return "'" + path.replace("'", "'\\''") + "'"


def atoi(value):
    m = re.match(r'\s*([+-]?\d+)', value)
    return int(m.group(1)) if m else 0


def version_pair(value):
    m = re.match(r'\s*([+-]?\d+)(?:\.(\d+))?', value)
    return (int(m[1]), int(m[2] or 0)) if m else (0, 0)


def distance(a, b):
    row = list(range(len(b) + 1))
    for i, ca in enumerate(a):
        nr = [i + 1]
        for j, cb in enumerate(b):
            nr.append(min(nr[-1] + 1, row[j+1] + 1, row[j] + (ca != cb)))
        row = nr
    return row[-1]


def suggestion(word, candidates):
    best, score = None, 4
    for name in candidates:
        d = distance(word, name)
        if d < score:
            best, score = name, d
    return best


class Expression:
    def __init__(self, parts=()):
        self.parts = list(parts)

    def evaluate(self, lookup):
        return ''.join(lookup(s) if isvar else s for isvar, s in self.parts)

    def display(self):
        return ''.join('${'+s+'}' if isvar else s for isvar, s in self.parts)

    def __bool__(self):
        return bool(self.parts)


class Scope:
    def __init__(self, parent=None):
        self.parent = parent
        self.values = {}
        self.rules = {}

    def get(self, name):
        if name in self.values:
            return self.values[name]
        return self.parent.get(name) if self.parent else ''

    def rule(self, name):
        if name in self.rules:
            return self.rules[name]
        return self.parent.rule(name) if self.parent else None


class Rule:
    def __init__(self, name):
        self.name = name
        self.bindings = {}


class Node:
    def __init__(self, path):
        self.path = path
        self.edge = None
        self.users = []
        self.validation_users = []
        self.discovered = False
        self.mtime = None
        self.dirty = False

    def stat(self, refresh=False):
        if refresh or self.mtime is None:
            try:
                self.mtime = os.stat(self.path).st_mtime_ns
            except (FileNotFoundError, NotADirectoryError):
                self.mtime = 0
            except OSError as e:
                raise NinjaError('stat(%s): %s' % (self.path, e.strerror))
        return self.mtime


class Edge:
    def __init__(self, rule, scope, index):
        self.rule = rule
        self.scope = scope
        self.index = index
        self.outputs = []
        self.inputs = []
        self.implicit_outputs = 0
        self.explicit_inputs = 0
        self.implicit_inputs = 0
        self.validations = []
        self.pool = ''
        self.dyndep = None
        self.dyndep_loaded = False
        self.deps_loaded = False
        self.dirty = False
        self.mark = 0
        self.reasons = []
        self.own_dirty = False
        self.finished = False
        self.failed = False
        self.started = False
        self.priority = 0

    @property
    def phony(self):
        return self.rule.name == 'phony'

    @property
    def normal_inputs(self):
        return self.inputs[:self.explicit_inputs + self.implicit_inputs]

    @property
    def order_inputs(self):
        return self.inputs[self.explicit_inputs + self.implicit_inputs:]

    def value(self, name, shell=True, chain=None):
        if name in ('in', 'in_newline'):
            paths = [n.path for n in self.inputs[:self.explicit_inputs]]
            return ('\n' if name == 'in_newline' else ' ').join(quote(p) if shell else p for p in paths)
        if name == 'out':
            nodes = self.outputs[:len(self.outputs)-self.implicit_outputs]
            return ' '.join(quote(n.path) if shell else n.path for n in nodes)
        if name in self.scope.values:
            return self.scope.values[name]
        expr = self.rule.bindings.get(name)
        if expr is not None:
            chain = list(chain or [])
            if name in chain:
                raise NinjaError('cycle in rule variables: ' + ' -> '.join(chain + [name]), 'fatal')
            chain.append(name)
            return expr.evaluate(lambda n: self.value(n, shell, chain))
        return self.scope.parent.get(name) if self.scope.parent else ''

    def command(self):
        return self.value('command')

    def description(self):
        return self.value('description')

    def flag(self, name):
        return bool(self.value(name, False))

    def add_discovered_inputs(self, nodes):
        for n in nodes:
            if n in self.inputs:
                continue
            ix = self.explicit_inputs + self.implicit_inputs
            self.inputs.insert(ix, n)
            self.implicit_inputs += 1
            n.users.append(self)


class State:
    def __init__(self):
        self.scope = Scope()
        self.scope.rules['phony'] = Rule('phony')
        self.pools = {'console': 1}
        self.nodes = {}
        self.edges = []
        self.defaults = []
        self.manifests = []

    def node(self, path):
        path = canonical(path)
        if path not in self.nodes:
            self.nodes[path] = Node(path)
        return self.nodes[path]

    def roots(self):
        roots = [n for e in self.edges for n in e.outputs if not n.users]
        if self.edges and not roots:
            raise NinjaError('could not determine root nodes of build graph')
        return roots

    def targets(self, names, use_defaults=True):
        if not names:
            return list(self.defaults) if self.defaults and use_defaults else self.roots()
        return [self.lookup(n) for n in names]

    def lookup(self, name):
        first_user = name.endswith('^')
        if first_user:
            name = name[:-1]
        name = canonical(name)
        n = self.nodes.get(name)
        if n is None:
            message = "unknown target '%s'" % name
            best = "ninja -h" if name == 'help' else suggestion(name, self.nodes)
            if best:
                message += ", did you mean '%s'?" % best
            raise NinjaError(message)
        if first_user:
            if not n.users:
                raise NinjaError("'%s' has no out edge" % name)
            n = n.users[0].outputs[0]
        return n
