"""Manifest syntax, including scoped includes and dollar escapes."""
import os
import re
from model import (NinjaError, Expression, Rule, Scope, Edge, canonical, atoi,
                   version_pair, warning, VERSION)

RULE_VARIABLES = {'command', 'depfile', 'deps', 'description', 'generator',
                  'pool', 'restat', 'rspfile', 'rspfile_content',
                  'msvc_deps_prefix', 'dyndep'}
ID = re.compile(r'[a-zA-Z0-9_.-]+')
SHORT_VAR = re.compile(r'[a-zA-Z0-9_-]+')

class Line:
    def __init__(self, text, mapping, start, after, terminated):
        self.text, self.mapping = text, mapping
        self.start, self.after, self.terminated = start, after, terminated


class Reader:
    def __init__(self, path, text):
        self.path, self.text = path, text
        self.lines = []
        pos = 0
        while pos < len(text):
            start = pos
            chars, mapping = [], []
            ended = False
            while pos < len(text):
                ch = text[pos]
                if ch == '$' and pos+1 < len(text) and text[pos+1] == '\n':
                    pos += 2
                    while pos < len(text) and text[pos] in ' \t':
                        pos += 1
                    continue
                if ch == '\n':
                    pos += 1
                    ended = True
                    break
                # $$ is kept as one lexical escape, not a continuation marker.
                if ch == '$' and pos+1 < len(text) and text[pos+1] == '$':
                    chars.extend(['$', '$']); mapping.extend([pos, pos+1]); pos += 2
                    continue
                chars.append(ch); mapping.append(pos); pos += 1
            self.lines.append(Line(''.join(chars), mapping, start, pos, ended))
        self.i = 0

    def error(self, message, line=None, col=None, pos=None):
        if pos is None:
            if line is not None:
                if col is None: col = len(line.text)
                pos = line.mapping[col] if col < len(line.mapping) else (line.after-1 if line.terminated else line.after)
            else:
                pos = self.lines[self.i].start if self.i < len(self.lines) else len(self.text)
        lineno = self.text.count('\n', 0, pos) + 1
        start = self.text.rfind('\n', 0, pos) + 1
        column = pos - start
        details = ''
        if column:
            end = self.text.find('\n', pos)
            if end < 0: end = len(self.text)
            context = self.text[start:end]
            # Long diagnostics use a bounded excerpt.
            if len(context) > 72:
                context = context[:72] + '...'
            details = context + '\n' + ' ' * min(column, 72) + '^ near here'
        raise NinjaError('%s:%d: %s\n%s\n' % (self.path, lineno, message, details))

    def expr(self, value, scope, line, offset=0):
        parts, literal = [], []
        i = 0
        def flush():
            if literal:
                parts.append((False, ''.join(literal))); literal.clear()
        while i < len(value):
            ch = value[i]
            if ch != '$':
                literal.append(ch); i += 1; continue
            if i+1 >= len(value):
                self.error('bad $-escape (literal $ must be written as $$)', line, offset+i)
            nxt = value[i+1]
            if nxt in '$ :':
                literal.append(nxt); i += 2
            elif nxt == '^':
                if version_pair(scope.get('ninja_required_version')) < (1, 14):
                    self.error("using $^ escape requires specifying 'ninja_required_version' with version greater or equal 1.14", line, max(0, offset-2))
                literal.append('\n'); i += 2
            elif nxt == '{':
                match = ID.match(value, i+2)
                if not match or match.end() >= len(value) or value[match.end()] != '}':
                    self.error('bad $-escape (literal $ must be written as $$)', line, offset+i)
                flush(); parts.append((True, match.group())); i = match.end()+1
            else:
                match = SHORT_VAR.match(value, i+1)
                if not match:
                    self.error('bad $-escape (literal $ must be written as $$)', line, offset+i)
                flush(); parts.append((True, match.group())); i = match.end()
        flush()
        return Expression(parts)

    def paths(self, line, start, scope):
        """Tokenize paths; an escaped delimiter belongs to the current path."""
        s, tokens, i = line.text, [], start
        while i < len(s):
            if s[i] == ' ':
                i += 1; continue
            if s[i] == '\t':
                self.error('tabs are not allowed, use spaces', line, i)
            if s[i] in ':|':
                j = i+1
                if s[i] == '|' and j < len(s) and s[j] in '|@': j += 1
                tokens.append((s[i:j], None, i)); i = j; continue
            j = i
            while j < len(s) and s[j] not in ' :|\t':
                if s[j] == '$' and j+1 < len(s):
                    if s[j+1] == '{':
                        close = s.find('}', j+2)
                        if close >= 0: j = close+1; continue
                    j += 2
                else:
                    j += 1
            raw = s[i:j]
            tokens.append(('path', self.expr(raw, scope, line, i), i))
            i = j
        return tokens

    def binding(self, line, scope):
        s = line.text
        start = len(s)-len(s.lstrip(' '))
        m = ID.match(s, start)
        if not m:
            self.error('expected variable name', line, start)
        name = m.group()
        p = m.end()
        while p < len(s) and s[p] == ' ': p += 1
        if p >= len(s) or s[p] != '=':
            got = 'newline' if p >= len(s) else ('identifier' if ID.match(s, p) else "'%s'" % s[p])
            self.error("expected '=', got %s" % got, line, p)
        p += 1
        while p < len(s) and s[p] == ' ': p += 1
        expr = self.expr(s[p:], scope, line, p)
        return name, expr

    def block(self, scope, kind=None):
        result = {}
        while self.i < len(self.lines):
            line = self.lines[self.i]
            s = line.text
            if s.lstrip(' ').startswith('#'):
                self.i += 1; continue
            if not s or not s.startswith(' '): break
            if not s.strip(' '): break
            if '\t' in s[:len(s)-len(s.lstrip(' '))+1]:
                self.error('tabs are not allowed, use spaces', line, 0)
            if not line.terminated:
                self.error('unexpected EOF', line)
            name, expr = self.binding(line, scope)
            if kind == 'rule' and name not in RULE_VARIABLES:
                self.error("unexpected variable '%s'" % name, line)
            if kind == 'pool' and name != 'depth':
                self.error("unexpected variable '%s'" % name, line)
            if kind == 'rule':
                result[name] = expr
            else:
                val = expr.evaluate(scope.get)
                result[name] = val
                if kind is None: scope.values[name] = val
                if kind == 'pool' and atoi(val) < 0:
                    self.error('invalid pool depth', line)
            self.i += 1
        return result


class ManifestParser:
    def __init__(self, state, options):
        self.state, self.options = state, options
        self.depth = 0

    def load(self, path, scope=None, origin=None):
        scope = scope or self.state.scope
        try:
            with open(path, 'r', encoding='utf-8', errors='surrogateescape', newline=None) as f:
                text = f.read()
        except OSError as e:
            message = "loading '%s': %s" % (path, e.strerror)
            if origin:
                reader, line = origin
                reader.error(message, line)
            raise NinjaError(message)
        if self.depth > 200:
            raise NinjaError('manifest include nesting is too deep')
        self.depth += 1
        self.state.manifests.append(path)
        reader = Reader(path, text)
        self.parse(reader, scope)
        self.depth -= 1

    def parse(self, r, scope):
        st = self.state
        while r.i < len(r.lines):
            line = r.lines[r.i]
            s = line.text
            if not s.strip(' ') or s.lstrip(' ').startswith('#'):
                r.i += 1; continue
            if s[0] == '\t': r.error('tabs are not allowed, use spaces', line, 0)
            if s[0] == ' ': r.error('unexpected indent', line, 0)
            if not line.terminated: r.error('unexpected EOF', line)
            m = ID.match(s)
            if not m: r.error('expected identifier', line, 0)
            keyword = m.group()
            pos = m.end()
            while pos < len(s) and s[pos] == ' ': pos += 1
            r.i += 1
            if keyword in ('rule', 'pool'):
                ident = ID.match(s, pos)
                if not ident:
                    r.error('expected %s name' % keyword, line, pos)
                name = ident.group()
                after = ident.end()
                while after < len(s) and s[after] == ' ': after += 1
                if after < len(s) and s[after] != '#':
                    r.error('expected newline, got identifier', line, after)
                if keyword == 'rule':
                    if name in scope.rules:
                        r.error("duplicate rule '%s'" % name, line, ident.end())
                    rule = Rule(name)
                    rule.bindings = r.block(scope, 'rule')
                    if not rule.bindings.get('command'):
                        r.error("expected 'command =' line")
                    if bool(rule.bindings.get('rspfile')) != bool(rule.bindings.get('rspfile_content')):
                        r.error('rspfile and rspfile_content need to be both specified')
                    scope.rules[name] = rule
                else:
                    if name in st.pools:
                        r.error("duplicate pool '%s'" % name, line, ident.end())
                    values = r.block(scope, 'pool')
                    if 'depth' not in values:
                        r.error("expected 'depth =' line")
                    st.pools[name] = atoi(values['depth'])
            elif keyword == 'build':
                tokens = r.paths(line, pos, scope)
                before, after, colon = [], [], None
                for ti, token in enumerate(tokens):
                    if token[0] == ':': colon = ti; break
                if colon is None:
                    r.error("expected ':', got newline ($ also escapes ':')", line)
                before = tokens[:colon]
                if not before or not any(t[0] == 'path' for t in before):
                    r.error('expected path', line, tokens[colon][2])
                # The rule name is a plain identifier, not an expanded path.
                p = tokens[colon][2]+1
                while p < len(s) and s[p] == ' ': p += 1
                rm = ID.match(s, p)
                if not rm: r.error('expected build command name', line, p)
                rule = scope.rule(rm.group())
                if not rule: r.error("unknown build rule '%s'" % rm.group(), line, p)
                after = r.paths(line, rm.end(), scope)
                local = Scope(scope)
                r.block(local)
                edge = Edge(rule, local, len(st.edges))
                implicit = False
                for typ, expr, tp in before:
                    if typ == '|': implicit = True; continue
                    if typ != 'path': r.error("expected ':', got '%s' ($ also escapes ':')" % typ, line, tp)
                    try: node = st.node(expr.evaluate(local.get))
                    except NinjaError as e: r.error(e.message)
                    if node in edge.outputs:
                        r.error('%s is defined as an output multiple times' % node.path)
                    if node.edge is not None:
                        r.error('multiple rules generate %s' % node.path)
                    edge.outputs.append(node)
                    if implicit: edge.implicit_outputs += 1
                mode = 'explicit'
                for typ, expr, tp in after:
                    if typ in ('|','||','|@'):
                        newmode = {'|':'implicit','||':'order','|@':'validation'}[typ]
                        if (mode == 'implicit' and typ == '|') or (mode == 'order' and typ in ('|','||')) or mode == 'validation':
                            r.error("expected newline, got '%s'" % typ, line, tp)
                        mode = newmode; continue
                    if typ != 'path': r.error("expected newline, got '%s'" % typ, line, tp)
                    try: node = st.node(expr.evaluate(local.get))
                    except NinjaError as e: r.error(e.message)
                    if mode == 'validation':
                        edge.validations.append(node); node.validation_users.append(edge)
                    else:
                        edge.inputs.append(node); node.users.append(edge)
                        if mode == 'explicit': edge.explicit_inputs += 1
                        if mode == 'implicit': edge.implicit_inputs += 1
                for node in edge.outputs: node.edge = edge
