                        r.error("unknown target '%s'" % path, line)
                    st.defaults.append(st.nodes[path])
            elif keyword in ('include','subninja'):
                tokens = r.paths(line, pos, scope)
                path = tokens[0][1].evaluate(scope.get) if tokens and tokens[0][1] else ''
                if len(tokens) > 1:
                    r.error('expected newline, got identifier', line, tokens[1][2])
                self.load(path, scope if keyword == 'include' else Scope(scope), (r, line))
            else:
                name, expr = r.binding(line, scope)
                value = expr.evaluate(scope.get)
                scope.values[name] = value
                if name == 'ninja_required_version':
                    ver = version_pair(value)
                    if ver > (1,14):
                        raise NinjaError('ninja version (%s) incompatible with build file ninja_required_version version (%s).' % (VERSION,value), 'fatal')
