    def __init__(self, rule, scope, index):
        self.rule = rule
        self.scope = scope
        self.index = index
        self.outputs = []
        self.inputs = []
        self.implicit_outputs = 0
        self.explicit_inputs = 0
        self.implicit_inputs = 0
        self.validations = []
        self.pool = ''
        self.dyndep = None
        self.dyndep_loaded = False
        self.deps_loaded = False
        self.dirty = False
        self.mark = 0
        self.reasons = []
        self.own_dirty = False
        self.finished = False
        self.failed = False
        self.started = False
        self.priority = 0

    @property
    def phony(self):
        return self.rule.name == 'phony'

    @property
    def normal_inputs(self):
        return self.inputs[:self.explicit_inputs + self.implicit_inputs]

    @property
    def order_inputs(self):
        return self.inputs[self.explicit_inputs + self.implicit_inputs:]

    def value(self, name, shell=True, chain=None):
        if name in ('in', 'in_newline'):
            paths = [n.path for n in self.inputs[:self.explicit_inputs]]
            return ('\n' if name == 'in_newline' else ' ').join(quote(p) if shell else p for p in paths)
        if name == 'out':
            nodes = self.outputs[:len(self.outputs)-self.implicit_outputs]
            return ' '.join(quote(n.path) if shell else n.path for n in nodes)
        if name in self.scope.values:
            return self.scope.values[name]
        expr = self.rule.bindings.get(name)
        if expr is not None:
            chain = list(chain or [])
            if name in chain:
                raise NinjaError('cycle in rule variables: ' + ' -> '.join(chain + [name]), 'fatal')
