def command_edges(targets, recurse=True):
    visited=set(); result=[]
    def visit(n):
        edge=n.edge
        if edge is None or edge in visited:return
        visited.add(edge)
        if recurse:
            for dep in edge.inputs: visit(dep)
        if not edge.phony: result.append(edge)
    for n in targets:visit(n)
    return result


def input_nodes(targets):
    seen=set(); result=[]
    def visit(n, include):
        if n in seen:return
        seen.add(n)
        if n.edge:
            for dep in n.edge.inputs:visit(dep,True)
        if include and (not n.edge or not n.edge.phony):result.append(n)
    # Each requested node can also be an input to another requested node.
    for n in targets:
        if n.edge:
            for dep in n.edge.inputs:visit(dep,True)
    return result


class Cleaner:
    def __init__(self,state,options):
        self.state,self.options=state,options
        self.verbose=options.verbose or options.dry
        self.removed=set();self.seen=set();self.count=0;self.failed=False

    def begin(self):out('Cleaning...'+ ('\n' if self.verbose else ''))
    def end(self):out(('' if self.verbose else ' ')+'%d files.\n'%self.count)
    def remove(self,path):
        if not path or path in self.removed:return
        self.removed.add(path)
        if not os.path.lexists(path):return
        if self.options.dry:
            self.count+=1
            out('Remove '+path+'\n')
            return
        try:os.remove(path)
        except OSError as e:
            err('ninja: error: remove(%s): %s\n'%(path,e.strerror));self.failed=True;return
        self.count+=1
        if self.verbose:out('Remove '+path+'\n')

    def extra(self,edge):
        self.remove(edge.value('depfile',False))
        self.remove(edge.value('rspfile',False))

    def target(self,n):
        if n in self.seen:return
        self.seen.add(n)
        edge=n.edge
        if not edge:return
        if not edge.phony:
            self.remove(n.path);self.extra(edge)
        for dep in edge.inputs:self.target(dep)

