"""Incremental dependency scanning and parallel command execution."""
import os
import re
import selectors
import signal
import subprocess
import time
from model import NinjaError, out, err, warning, quote
from logs import command_hash, read_depfile


class Scanner:
    def __init__(self,state,options,logs):
        self.state,self.options,self.logs=state,options,logs
        self.edges=set()
        self.validations=[]
        self.stack=[]

    def load_implicit(self,edge):
        if edge.deps_loaded:return []
        edge.deps_loaded=True
        reasons=[]
        depstype=edge.value('deps',False)
        if depstype and depstype not in ('gcc','msvc'):
            raise NinjaError("unknown deps type '%s'"%depstype,'fatal')
        paths=[]
        if depstype:
            record=self.logs.deps.get(edge.outputs[0].path)
            if record is None:
                reasons.append("deps for '%s' are missing"%edge.outputs[0].path)
            elif edge.outputs[0].stat()>record[0]:
                reasons.append("stored deps info out of date for '%s' (%d vs %d)"%(edge.outputs[0].path,record[0],edge.outputs[0].stat()))
            else:
                paths=[n.path for n in record[1]]
        else:
            depfile=edge.value('depfile',False)
            if depfile:
                parsed=read_depfile(depfile)
                if parsed is None:
                    reasons.append("depfile '%s' is missing"%depfile)
                elif parsed[0] and self.state.node(parsed[0][0]) not in edge.outputs:
                    reasons.append("expected depfile '%s' to mention '%s', got '%s'"%(depfile,edge.outputs[0].path,parsed[0][0]))
                else:
                    paths=parsed[1]
        for path in paths:
            n=self.state.node(path)
            if n not in edge.inputs:
                if n.edge is None:n.discovered=True
                edge.add_discovered_inputs([n])
        edge.deps_reasons=reasons
        return reasons

    def visit(self,node,parent=None):
        node.stat()
        edge=node.edge
        if edge is None:
            node.dirty=node.mtime==0
            if node.dirty and not node.discovered:
                if parent:
                    raise NinjaError("'%s', needed by '%s', missing and no known rule to make it"%(node.path,parent.path))
                raise NinjaError("'%s' missing and no known rule to make it"%node.path)
            return
        self.edges.add(edge)
        if edge.finished:return
        if edge.mark==2:return
        if edge.mark==1:
            ix=next((i for i,n in enumerate(self.stack) if n.edge==edge),0)
            chain=[n.path for n in self.stack[ix:]]+[node.path]
            suffix=''
            if len(chain)==2 and edge.phony and self.options.phonycycle=='err':suffix=' [-w phonycycle=err]'
            raise NinjaError('dependency cycle: '+' -> '.join(chain)+suffix)
        edge.mark=1;self.stack.append(node)
        for n in edge.outputs:n.stat()
        if edge.dyndep and not edge.dyndep_loaded:
            self.visit(edge.dyndep,node)
            if not edge.dyndep.dirty or (edge.dyndep.edge and edge.dyndep.edge.finished):
                from dyndep import load_dyndep
                load_dyndep(self.state,edge.dyndep,self.options)
        if not edge.phony:self.load_implicit(edge)
        for dep in edge.inputs:
            self.visit(dep,node)
        self.validations.extend(n for n in edge.validations if n.edge)
        normal=edge.normal_inputs
        dirty_inputs=[n for n in normal if n.dirty]
        newest=max(normal,key=lambda n:n.mtime or 0) if normal else None
        newest_time=newest.mtime if newest else 0
        reasons=list(getattr(edge,'deps_reasons',[]))
        edge.own_dirty=bool(reasons)
        if edge.phony:
            edge.dirty=bool(dirty_inputs) if edge.inputs else any(n.mtime==0 for n in edge.outputs)
            for n in edge.outputs:
                n.dirty=edge.dirty
