#!/usr/bin/env python3
"""A standalone, manifest-driven build runner."""
import os
import re
import signal
import sys
import time
from model import NinjaError, State, out, err, warning, canonical
from parser import ManifestParser
from cli import main_options
from logs import Logs
from tools import run_tool
from engine import Builder


def stats(state):
    # Counts are useful even on platforms with coarse operation timers.
    out('metric          \tcount \tavg (us) \ttotal (ms)\n')
    for name,count in [('.ninja parse',len(state.manifests)),('.ninja_log load',1),('.ninja_deps load',1),('node stat',len(state.nodes)+1)]:
        out('%-15s\t%-6d\t%-8.1f\t%.1f\n'%(name,count,0.,0.))
    buckets=4
    while buckets<len(state.nodes):buckets*=2
    out('\npath->node hash load %.2f (%d entries / %d buckets)\n'%(len(state.nodes)/buckets,len(state.nodes),buckets))


def execute():
    options=main_options(sys.argv[1:])
    if options.directory is not None:
        if not options.tool and not options.quiet:out("ninja: Entering directory `%s'\n"%options.directory)
        try:os.chdir(options.directory)
        except OSError as e:raise NinjaError("chdir to '%s' - %s"%(options.directory,e.strerror),'fatal')
    if not options.tool and not options.dry and not options.explicit_jobs:
        flags=os.environ.get('MAKEFLAGS','')
        if re.search(r'--jobserver-auth=\d+,\d+',flags):
            warning('Ignoring jobserver: Pipe-based protocol is not supported! [%s]'%flags)
    for attempt in range(100):
        state=State()
        ManifestParser(state,options).load(options.filename)
        logs=Logs(state,options)
        if options.tool:
            return run_tool(options.tool,options.toolargs,state,options,logs)
        logs.load_build();logs.load_deps()
        manifest=state.nodes.get(canonical(options.filename))
        if manifest and manifest.edge:
            oldtime=manifest.stat()
            regeneration=Builder(state,options,logs)
            result=regeneration.run([manifest],False)
            if result:
                if result!=130:
                    # The underlying build already printed its stopping reason.
                    err("ninja: error: rebuilding '%s': subcommand failed\n"%options.filename)
                return result
            if regeneration.actual_finished and not options.dry:
                if manifest.stat(True)!=oldtime:
                    continue
            for edge in state.edges:
                edge.mark=0;edge.priority=0
        targets=state.targets(options.targets)
        builder=Builder(state,options,logs)
        code=builder.run(targets)
        if 'stats' in options.debug:stats(state)
        return code
    raise NinjaError("manifest '%s' still dirty after 100 tries, perhaps system time is not set"%options.filename)


def main():
    try:
        return execute()
    except NinjaError as e:
        err('ninja: %s: '%e.kind+e.message+('' if e.message.endswith('\n') else '\n'))
        return e.code
    except BrokenPipeError:
        return 1
    except KeyboardInterrupt:
        out('ninja: build stopped: interrupted by user.\n')
        return 130


if __name__=='__main__':
    # Match byte-preserving manifest and subprocess output on Unix.
    for stream in (sys.stdout,sys.stderr):
        if hasattr(stream,'reconfigure'):
            stream.reconfigure(errors='surrogateescape')
    sys.exit(main())
